CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;

-- DELIV-007: completed copies to every party. A secure link per recipient opens only after a code sent to that
-- mailbox; attachments go out when the account chose them and the files fit. Copy links and account settings are
-- installation state (not archived).
CREATE TABLE iw_copy_links (token_hash TEXT PRIMARY KEY, envelope_id TEXT NOT NULL REFERENCES iw_envelopes(id), party INTEGER NOT NULL, email TEXT NOT NULL, code_hash TEXT, code_expires INTEGER, code_attempts INTEGER NOT NULL DEFAULT 0, code_sent_at INTEGER, code_generation INTEGER NOT NULL DEFAULT 0, session_hash TEXT, session_expires INTEGER, UNIQUE(envelope_id, party));
CREATE TABLE iw_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
ALTER TABLE iw_mail ADD COLUMN attach INTEGER NOT NULL DEFAULT 0;

-- ROUTE-009: a member's adopted signature, saved when they sign with their Inkwell session and reused until they change
-- it. Installation state (not archived), like member roles.
CREATE TABLE iw_member_marks (operator_id TEXT PRIMARY KEY, signature TEXT NOT NULL, updated_at TEXT NOT NULL);

-- ADMIN-001: an envelope shared with a member to view or to edit. Permission state of this installation (not archived),
-- erased with the envelope.
CREATE TABLE iw_shares (envelope_id TEXT NOT NULL REFERENCES iw_envelopes(id), operator_id TEXT NOT NULL, access TEXT NOT NULL CHECK(access IN ('view','edit')), granted_by TEXT NOT NULL, granted_at TEXT NOT NULL, PRIMARY KEY(envelope_id, operator_id));
CREATE INDEX iw_shares_operator ON iw_shares(operator_id);

-- SIGNX-001: what a signer has entered so far, saved so they can finish later from the same link. Unsigned entries,
-- not evidence and not archived; cleared when they sign or the envelope is declined or voided, erased with the envelope.
ALTER TABLE iw_signers ADD COLUMN progress TEXT;

-- ROUTE-008: the account's shared contact book, keyed by lower-case email. Installation state (not archived), like roles.
CREATE TABLE iw_contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, company TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX iw_contacts_name ON iw_contacts(name COLLATE NOCASE);

-- TMPL-001: reusable templates: one fixed PDF with roles, fields and envelope settings, kept apart from envelopes.
CREATE TABLE iw_templates (id TEXT PRIMARY KEY, created_by TEXT NOT NULL, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE iw_template_blobs (template_id TEXT NOT NULL REFERENCES iw_templates(id), part INTEGER NOT NULL, data BLOB NOT NULL CHECK(length(data)<102400), PRIMARY KEY(template_id,part));

-- TMPL-002: shared folders that hold templates (a template with no folder is in its maker's personal folder), and shares
-- of a template or a folder with a member to use or to edit. Shares are installation state, like envelope shares.
CREATE TABLE iw_template_folders (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL, created_at TEXT NOT NULL);
ALTER TABLE iw_templates ADD COLUMN folder_id TEXT;
CREATE TABLE iw_template_shares (subject TEXT NOT NULL CHECK(subject IN ('template','folder')), subject_id TEXT NOT NULL, operator_id TEXT NOT NULL, access TEXT NOT NULL CHECK(access IN ('use','edit')), granted_by TEXT NOT NULL, granted_at TEXT NOT NULL, PRIMARY KEY(subject,subject_id,operator_id));

-- DELIV-008: sender notifications. Each notice is a feed row for one member; its channel posts wait in iw_notice_posts
-- until sent. Each member's choices per event and channel, and the webhook URLs they connected (sealed, with a masked
-- form to show), are installation state.
CREATE TABLE iw_notices (id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, envelope_id TEXT NOT NULL, event TEXT NOT NULL, at TEXT NOT NULL, title TEXT NOT NULL, recipient TEXT NOT NULL DEFAULT '');
CREATE INDEX iw_notices_by_operator ON iw_notices(operator_id, at DESC, id DESC);
CREATE TABLE iw_notice_posts (id TEXT PRIMARY KEY, notice_id TEXT NOT NULL, operator_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('slack','teams','nook')), body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', result TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX iw_notice_posts_pending ON iw_notice_posts(state);
CREATE TABLE iw_notice_prefs (operator_id TEXT NOT NULL, event TEXT NOT NULL, channel TEXT NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(operator_id, event, channel));
CREATE TABLE iw_notice_channels (operator_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('slack','teams','nook')), sealed TEXT NOT NULL, masked TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(operator_id, channel));

-- Keep retention clocks outside canonical import values so undo remains exact.
CREATE TABLE iw_import_retention (
 job_id TEXT PRIMARY KEY,
 records TEXT NOT NULL CHECK(json_valid(records)),
 imported_at TEXT,
 due TEXT, warned_at TEXT, purge_at TEXT,
 purged_at TEXT
);
CREATE TABLE iw_import_holds (record_id TEXT PRIMARY KEY, reason TEXT NOT NULL, actor TEXT NOT NULL, placed_at TEXT NOT NULL);
CREATE TABLE iw_import_hold_events (id TEXT PRIMARY KEY, record_id TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE iw_import_retention_mail (id TEXT PRIMARY KEY, group_id TEXT NOT NULL, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', provider TEXT, provider_message_id TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), sent_at TEXT);
CREATE INDEX iw_import_retention_mail_provider_message ON iw_import_retention_mail(provider,provider_message_id);
-- Existing jobs have valid DocuSeal terminal times even when the owner undid them.
-- This edition uses Base's default JSON plan storage, including ordered chunks.
INSERT INTO iw_import_retention(job_id,records)
SELECT j.id, json_group_array(json_object('id',json_extract(f.value,'$.targetId'),'at',json_extract(f.value,'$.value.completedAt')))
FROM ik_jobs j,
 json_each(CASE WHEN json_extract(j.plan_json,'$.d1Plan')=1 THEN (SELECT group_concat(body,'') FROM (SELECT body FROM ik_d1_plan_chunks WHERE job_id=j.id ORDER BY ordinal)) ELSE j.plan_json END,'$.entries') e,
 json_each(e.value,'$.effects') f
WHERE j.destination='inkwell' AND j.namespace='docuseal-completed-archive' AND json_extract(f.value,'$.targetKind')='archive'
GROUP BY j.id;
INSERT OR IGNORE INTO iw_import_retention(job_id,records) SELECT id,'[]' FROM ik_jobs WHERE destination='inkwell' AND namespace='docuseal-completed-archive';
-- Native imported envelopes share the ordinary owner-erasure door.
CREATE TRIGGER iw_import_retention_envelope_erased AFTER DELETE ON iw_envelopes BEGIN
 DELETE FROM iw_import_retention_mail WHERE group_id='envelope:'||OLD.id;
END;

-- COMPLY-002: installation member activity; document custody remains unchanged.
CREATE TABLE iw_member_access (
 operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id) ON DELETE CASCADE,
 last_access_at TEXT NOT NULL
);

-- PREP-011: account-wide default and permanent history of actual changes.
CREATE TABLE iw_freeform_policy (
  id INTEGER PRIMARY KEY CHECK(id=1),
  enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),
  version INTEGER NOT NULL CHECK(version>=0),
  actor TEXT,
  at TEXT
);
INSERT INTO iw_freeform_policy(id,enabled,version) VALUES(1,0,0);
CREATE TABLE iw_freeform_history (
  version INTEGER PRIMARY KEY CHECK(version>0),
  actor TEXT NOT NULL,
  at TEXT NOT NULL,
  before_value INTEGER NOT NULL CHECK(before_value IN (0,1)),
  after_value INTEGER NOT NULL CHECK(after_value IN (0,1) AND after_value<>before_value)
);
CREATE TRIGGER iw_freeform_history_no_update BEFORE UPDATE ON iw_freeform_history BEGIN SELECT RAISE(ABORT,'Free-form setting history is append-only'); END;
CREATE TRIGGER iw_freeform_history_no_delete BEFORE DELETE ON iw_freeform_history BEGIN SELECT RAISE(ABORT,'Free-form setting history is append-only'); END;

-- SEND-001: an installation-local live revision survives edits, deletion and restoration of earlier content.
CREATE TABLE iw_template_revisions (template_id TEXT PRIMARY KEY, revision TEXT NOT NULL);
INSERT INTO iw_template_revisions SELECT id,lower(hex(randomblob(16))) FROM iw_templates;
CREATE TRIGGER iw_template_revision_insert AFTER INSERT ON iw_templates BEGIN
  INSERT INTO iw_template_revisions VALUES(NEW.id,lower(hex(randomblob(16)))) ON CONFLICT(template_id) DO UPDATE SET revision=lower(hex(randomblob(16)));
END;
CREATE TRIGGER iw_template_revision_update AFTER UPDATE ON iw_templates BEGIN
  INSERT INTO iw_template_revisions VALUES(NEW.id,lower(hex(randomblob(16)))) ON CONFLICT(template_id) DO UPDATE SET revision=lower(hex(randomblob(16)));
END;
CREATE TRIGGER iw_template_revision_delete AFTER DELETE ON iw_templates BEGIN
  INSERT INTO iw_template_revisions VALUES(OLD.id,lower(hex(randomblob(16)))) ON CONFLICT(template_id) DO UPDATE SET revision=lower(hex(randomblob(16)));
END;

-- API-001: credentials belong to this installation, never its document archives.
-- The token is revealed only by the successful mint/rotate response; receipts hold metadata only.
CREATE TABLE iw_api_keys (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, member_id TEXT NOT NULL,
 member_version INTEGER NOT NULL, member_role TEXT NOT NULL CHECK(member_role IN ('owner','admin','sender')),
 token_hash TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, last_four TEXT NOT NULL,
 scopes TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
 expires_at TEXT NOT NULL, revoked_at TEXT, suspended_at TEXT,
 rotated_to TEXT, version INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX iw_api_keys_member ON iw_api_keys(member_id);
-- Remember authority loss when it happens, even if nobody calls the key until after restoration.
CREATE TRIGGER iw_api_keys_member_changed AFTER UPDATE OF status,role,version ON oa_operators
WHEN NEW.status<>'active' OR NEW.role<>OLD.role OR NEW.version<>OLD.version
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=NEW.id; END;
CREATE TRIGGER iw_api_keys_member_deleted AFTER DELETE ON oa_operators
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=OLD.id; END;
CREATE TRIGGER iw_api_keys_sender_narrowed AFTER UPDATE OF role ON iw_member_roles
WHEN OLD.role='sender' AND NEW.role<>'sender'
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=NEW.operator_id AND member_role='sender'; END;
CREATE TRIGGER iw_api_keys_sender_removed AFTER DELETE ON iw_member_roles WHEN OLD.role='sender'
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=OLD.operator_id AND member_role='sender'; END;
CREATE TRIGGER iw_api_keys_share_narrowed AFTER UPDATE OF access ON iw_shares WHEN OLD.access='edit' AND NEW.access='view'
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=NEW.operator_id AND member_role='sender'; END;
CREATE TRIGGER iw_api_keys_share_removed AFTER DELETE ON iw_shares
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=OLD.operator_id AND member_role='sender'; END;
CREATE TRIGGER iw_api_keys_template_share_narrowed AFTER UPDATE OF access ON iw_template_shares WHEN OLD.access='edit' AND NEW.access='use'
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=NEW.operator_id AND member_role='sender'; END;
CREATE TRIGGER iw_api_keys_template_share_removed AFTER DELETE ON iw_template_shares
BEGIN UPDATE iw_api_keys SET suspended_at=COALESCE(suspended_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE member_id=OLD.operator_id AND member_role='sender'; END;

-- Follow-up authorizations are not credentials. Private replies have their own read door.
CREATE TABLE iw_followup_grants(envelope_id TEXT NOT NULL,version INTEGER NOT NULL,state TEXT NOT NULL,member_id TEXT NOT NULL,member_version INTEGER NOT NULL,member_role TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(envelope_id,version));
CREATE TABLE iw_followup_states(envelope_id TEXT NOT NULL,signer INTEGER NOT NULL,identity TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(envelope_id,signer));
CREATE TABLE iw_followup_replies(id TEXT PRIMARY KEY,envelope_id TEXT NOT NULL,signer INTEGER NOT NULL,data TEXT NOT NULL);
CREATE TABLE iw_followup_capabilities(cap_hash TEXT PRIMARY KEY,envelope_id TEXT NOT NULL,signer INTEGER NOT NULL,token_hash TEXT NOT NULL,grant_version INTEGER NOT NULL);
CREATE TABLE iw_followup_receipts(event_id TEXT PRIMARY KEY,received_at TEXT NOT NULL);
ALTER TABLE iw_mail ADD COLUMN followup_version INTEGER;
ALTER TABLE iw_mail ADD COLUMN followup_envelope_version INTEGER;
CREATE TRIGGER iw_followup_member_changed AFTER UPDATE OF status,role,version ON oa_operators
WHEN NEW.status!=OLD.status OR NEW.role!=OLD.role OR NEW.version!=OLD.version BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=OLD.id AND state='active';
 UPDATE iw_mail SET state='cancelled',body='' WHERE state='pending' AND followup_version IS NOT NULL AND envelope_id IN (SELECT envelope_id FROM iw_followup_grants WHERE member_id=OLD.id AND state='suspended');
END;
CREATE TRIGGER iw_followup_member_removed BEFORE DELETE ON oa_operators BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=OLD.id AND state='active';
END;
CREATE TRIGGER iw_followup_role_narrowed AFTER UPDATE OF role ON iw_member_roles WHEN NEW.role='viewer' BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=NEW.operator_id AND state='active';
END;
CREATE TRIGGER iw_followup_role_removed AFTER DELETE ON iw_member_roles BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=OLD.operator_id AND state='active';
END;
CREATE TRIGGER iw_followup_share_removed AFTER DELETE ON iw_shares WHEN OLD.access='edit' BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=OLD.operator_id AND envelope_id=OLD.envelope_id AND member_role='sender' AND state='active' AND EXISTS(SELECT 1 FROM iw_envelopes WHERE id=OLD.envelope_id AND json_extract(data,'$.createdBy')!=OLD.operator_id);
END;
CREATE TRIGGER iw_followup_share_narrowed AFTER UPDATE OF access ON iw_shares WHEN OLD.access='edit' AND NEW.access!='edit' BEGIN
 UPDATE iw_followup_grants SET state='suspended' WHERE member_id=OLD.operator_id AND envelope_id=OLD.envelope_id AND member_role='sender' AND state='active' AND EXISTS(SELECT 1 FROM iw_envelopes WHERE id=OLD.envelope_id AND json_extract(data,'$.createdBy')!=OLD.operator_id);
END;
CREATE TRIGGER iw_followup_closed AFTER UPDATE OF data ON iw_envelopes WHEN json_extract(NEW.data,'$.status')!='awaiting_signature' BEGIN
 UPDATE iw_followup_grants SET state='ended' WHERE envelope_id=NEW.id AND state='active';
 DELETE FROM iw_followup_capabilities WHERE envelope_id=NEW.id;
 UPDATE iw_mail SET state='cancelled',body='' WHERE envelope_id=NEW.id AND state='pending' AND followup_version IS NOT NULL;
END;
CREATE TRIGGER iw_followup_drop_suspended_capabilities AFTER UPDATE OF state ON iw_followup_grants
WHEN NEW.state IN ('suspended','ended') BEGIN
 DELETE FROM iw_followup_capabilities WHERE envelope_id=NEW.envelope_id;
 UPDATE iw_mail SET state='cancelled',body='' WHERE envelope_id=NEW.envelope_id AND state='pending' AND followup_version IS NOT NULL;
END;

